from pathlib import Path
import hashlib, json
root = Path.home() / "cyber-lab"
baseline = json.loads(Path("integrity-baseline.json").read_text())
current = {}
for path in root.rglob("*"):
    if path.is_file():
        try:
            current[str(path.relative_to(root))] = hashlib.sha256(path.read_bytes()).hexdigest()
        except OSError:
            pass
for name in sorted(set(baseline) | set(current)):
    if name not in baseline:
        print("NEW:", name)
    elif name not in current:
        print("MISSING:", name)
    elif baseline[name] != current[name]:
        print("CHANGED:", name)

from pathlib import Path
from collections import Counter
text = Path("app.log").read_text(errors="replace").upper()
counts = Counter()
for line in text.splitlines():
    for level in ("CRITICAL", "ERROR", "WARNING", "INFO", "DEBUG"):
        if level in line:
            counts[level] += 1
            break
for level, total in counts.most_common():
    print(f"{level}: {total}")

