for target in scope:
    if target == "localhost":
        print("APPROVED:", target)
        continue
    try:
        ip = ipaddress.ip_address(target)
        print(("APPROVED:" if ip.is_loopback else "REJECTED:"), target)
    except ValueError:
        print("REJECTED:", target)

from pathlib import Path
import re
root = Path(".")
pattern = re.compile(r"(?i)(api[_-]?key|secret|password)\s*[:=]\s*['\"][^'\"]{8,}")
for path in root.rglob("*"):
    if path.is_file() and path.suffix in {".py", ".js", ".html", ".json", ".env.example"}:
        try:
            for line_no, line in enumerate(path.read_text(errors="ignore").splitlines(), 1):
                if pattern.search(line):
                    print(f"REVIEW {path}:{line_no} — possible hard-coded secret")
        except OSError:
            pass
